SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
def task_func():
    class PostRequestHandler(http.server.BaseHTTPRequestHandler):
        def do_POST(self):
            # Ensure content-type header is 'application/json'
            content_type = self.headers.get('Content-Type')
            if content_type != 'application/json':
                self.send_error(400, 'Content-Type header is not application/json')
                response_body = json.dumps({
                    'status': 'error',
                    'message': 'Content-Type header is not application/json'
                })
                self._send_response(response_body)
                return

            # Read the request body
            content_length = int(self.headers.get('Content-Length', 0))
            request_body = self.rfile.read(content_length).decode('utf-8')

            try:
                # Parse the request body as JSON
                request_json = json.loads(request_body)
            except json.JSONDecodeError:
                self.send_error(400, 'Invalid JSON')
                response_body = json.dumps({
                    'status': 'error',
                    'message': 'Invalid JSON'
                })
                self._send_response(response_body)
                return

            # Check if 'data' key exists in the JSON object
            if 'data' not in request_json:
                self.send_error(400, 'No data key in request')
                response_body = json.dumps({
                    'status': 'error',
                    'message': 'No data key in request'
                })
                self._send_response(response_body)
                return

            # Respond with success if validation passes
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            response_body = json.dumps(SUCCESS_RESPONSE)
            self._send_response(response_body)

        def _send_response(self, response_body):
            # Send headers and response body
            self.send_header('Content-Length', str(len(response_body)))
            self.end_headers()
            self.wfile.write(response_body.encode('utf-8'))

    return PostRequestHandler

