def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    # Step 1: Validate the file existence
    if not os.path.exists(file_path):
        raise ValueError(f"The file '{file_path}' does not exist.")

    # Step 2: Load and parse the JSON file
    try:
        with open(file_path, 'r') as file:
            data = json.load(file)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON format.")

    # Step 3: Validate required attributes
    required_fields = INPUT_JSON.get("required", [])
    for field in required_fields:
        if field not in data:
            raise ValueError(f"Missing required attribute: '{field}'")

    # Step 4: Validate attribute types
    for field, field_schema in INPUT_JSON.get("properties", {}).items():
        if field in data:
            expected_type = field_schema.get("type")
            if not isinstance(data[field], expected_type):
                raise ValueError(f"Type mismatch for attribute '{field}': Expected {expected_type.__name__}, got {type(data[field]).__name__}")

    # Step 5: Validate email format
    if "email" in data:
        email = data["email"]
        if not re.match(EMAIL_REGEX, email):
            raise ValueError(f"Invalid email format: '{email}'")

    # Step 6: Retrieve the specified attribute
    if attribute not in data:
        raise ValueError(f"Attribute '{attribute}' not found in JSON data.")

    return data[attribute]

