import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    """
    Processes a JSON string by:
    1. Removing None values.
    2. Counting the frequency of each unique value.
    3. Replacing all email addresses with the placeholder "None".

    Args:
        json_str (str): A JSON string.

    Returns:
        dict: A dictionary containing:
            "data": Processed JSON data.
            "value_counts": A Counter object with the frequency of each unique value.
    """
    def clean_data(data):
        """
        Recursively process the JSON data to:
        - Remove None values.
        - Replace email addresses with the placeholder "None".
        """
        if isinstance(data, dict):
            return {
                key: clean_data(value)
                for key, value in data.items()
                if value is not None
            }
        elif isinstance(data, list):
            return [clean_data(item) for item in data if item is not None]
        elif isinstance(data, str):
            # Check if the string is an email and replace it with "None"
            if re.match(r"[^@]+@[^@]+\.[^@]+", data):
                return REPLACE_NONE
            return data
        else:
            return data

    # Parse the JSON string
    try:
        parsed_data = json.loads(json_str)
    except json.JSONDecodeError:
        return {"data": None, "value_counts": Counter()}

    # Process the data
    cleaned_data = clean_data(parsed_data)

    # Flatten the data for counting purposes
    def flatten(data):
        if isinstance(data, dict):
            for value in data.values():
                yield from flatten(value)
        elif isinstance(data, list):
            for item in data:
                yield from flatten(item)
        else:
            yield data

    # Count the frequency of each unique value
    flattened_data = list(flatten(cleaned_data))
    value_counts = Counter(flattened_data)

    # Return the result
    return {
        "data": cleaned_data,
        "value_counts": value_counts
    }

