import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        # Validate and load JSON data
        if not json_data:
            raise ValueError("The JSON data is empty or malformed.")

        try:
            data = json.loads(json_data)
        except json.JSONDecodeError:
            raise ValueError("The JSON data is malformed.")

        # Validate data format
        if not isinstance(data, list):
            raise ValueError("The JSON data must be a list of dictionaries.")

        validated_data = []
        for record in data:
            if not isinstance(record, dict):
                raise ValueError("Each record in the JSON data must be a dictionary.")
            if "Country" not in record or "Population" not in record:
                raise ValueError("Each record must contain 'Country' and 'Population' keys.")
            if not isinstance(record["Country"], str):
                raise ValueError("Country name must be a string.")
            if not isinstance(record["Population"], (int, float)) or record["Population"] < 0:
                raise ValueError("Population must be a non-negative number.")

            # Round population down to nearest integer if it's a float
            population = math.floor(record["Population"]) if isinstance(record["Population"], float) else record["Population"]

            validated_data.append({"Country": record["Country"], "Population": population})

        # Create DataFrame
        df = pd.DataFrame(validated_data, columns=["Country", "Population"])

        # Generate file path
        file_path = os.path.join(output_dir, file_name)

        # Write DataFrame to CSV
        try:
            df.to_csv(file_path, index=False)
        except Exception as e:
            raise IOError(f"Failed to write the file to the specified directory: {e}")

        return file_path, df
    except ValueError as ve:
        raise ve
    except IOError as ioe:
        raise ioe
